import { apiClient } from "@/lib/api-client";
import { uploadToCloudinary } from "@/lib/upload";
import type { Favorite } from "@/types/wishbook";

export type CreateFavoritePayload = Omit<
  Favorite,
  "id" | "userId" | "createdAt"
> & {
  // createdAt is generated by backend; we don't send it
  createdAt?: never;
};

export async function createFavorite(
  payload: CreateFavoritePayload,
): Promise<Favorite> {
  const body = {
    categoryId: payload.categoryId,
    title: payload.title,
    image: payload.image,
    rating: payload.rating,
    mood: payload.mood,
    whyILike: payload.whyILike,
    timePeriod: payload.timePeriod,
    recommendedTime: payload.recommendedTime,
    tags: payload.tags,
    fields: payload.fields,
    status: payload.status,
  };
  const { data } = await apiClient.post<Favorite>("/favorites", body);
  // Coerce createdAt back to Date for client type safety
  return {
    ...data,
    createdAt: new Date(data.createdAt),
  };
}

const PROFILE_PREVIEW_LIMIT = 6;
const COLLECTION_PAGE_SIZE = 15;

export async function getFavorites(
  categoryId?: string,
): Promise<Favorite[]> {
  const params = categoryId ? { categoryId } : undefined;
  const { data } = await apiClient.get<Favorite[]>("/favorites", { params });
  return data.map((fav) => ({
    ...fav,
    createdAt: new Date(fav.createdAt),
  }));
}

export type FavoritesPageResponse = {
  items: Favorite[];
  hasMore: boolean;
  nextOffset: number;
};

/** Paginated favorites for owner collection page (infinite scroll). */
export async function getFavoritesPage(
  offset: number,
  categoryId?: string,
  search?: string,
  sortBy: 'newest' | 'oldest' | 'rating_desc' | 'rating_asc' = 'newest',
  status?: string,
): Promise<FavoritesPageResponse> {
  const params: Record<string, string> = {
    limit: String(COLLECTION_PAGE_SIZE),
    offset: String(offset),
    sortBy,
  };
  if (categoryId) params.categoryId = categoryId;
  if (search?.trim()) params.q = search.trim();
  if (status && status !== 'all') params.status = status;
  const { data } = await apiClient.get<FavoritesPageResponse>("/favorites", {
    params,
  });
  return {
    items: (data.items ?? []).map((fav) => ({
      ...fav,
      createdAt: new Date(fav.createdAt),
    })),
    hasMore: data.hasMore ?? false,
    nextOffset: data.nextOffset ?? offset + (data.items?.length ?? 0),
  };
}

export { PROFILE_PREVIEW_LIMIT, COLLECTION_PAGE_SIZE };

/**
 * Mood-filtered public favorites for the /mood discovery pages.
 * Backend uses `mood && ARRAY[:moods]` overlap (GIN-indexed). Empty moods
 * returns the newest published favorites.
 */
export async function getFavoritesByMoods(
  offset: number,
  moods: string[],
  limit: number = COLLECTION_PAGE_SIZE,
  sortBy: 'newest' | 'oldest' | 'rating_desc' | 'rating_asc' = 'newest',
): Promise<FavoritesPageResponse> {
  const params: Record<string, string> = {
    limit: String(limit),
    offset: String(offset),
    sortBy,
  };
  const cleaned = moods.map((m) => m.trim()).filter(Boolean);
  if (cleaned.length > 0) params.moods = cleaned.join(',');
  const { data } = await apiClient.get<FavoritesPageResponse>('/favorites', {
    params,
  });
  return {
    items: (data.items ?? []).map((fav) => ({
      ...fav,
      createdAt: new Date(fav.createdAt),
    })),
    hasMore: data.hasMore ?? false,
    nextOffset: data.nextOffset ?? offset + (data.items?.length ?? 0),
  };
}

/**
 * Blind-recommendation roulette. Returns a single random PUBLISHED favorite
 * from the public pool. Optional `exclude` keeps recent spins from
 * resurfacing during rapid clicks.
 */
export async function getRandomFavorite(
  exclude?: string[],
): Promise<Favorite | null> {
  const params: Record<string, string> = {};
  const cleaned = (exclude ?? []).map((s) => s.trim()).filter(Boolean);
  if (cleaned.length > 0) params.exclude = cleaned.join(",");
  const { data } = await apiClient.get<Favorite | null>("/favorites/random", {
    params,
  });
  if (!data) return null;
  return { ...data, createdAt: new Date(data.createdAt) };
}

export async function getFavorite(id: string): Promise<Favorite> {
  const { data } = await apiClient.get<Favorite>(`/favorites/${id}`);
  return {
    ...data,
    createdAt: new Date(data.createdAt),
  };
}

export type UpdateFavoritePayload = Partial<
  Omit<Favorite, "id" | "userId" | "createdAt">
>;

export async function updateFavorite(
  id: string,
  payload: UpdateFavoritePayload,
): Promise<Favorite> {
  const { data } = await apiClient.patch<Favorite>(`/favorites/${id}`, payload);
  return {
    ...data,
    createdAt: new Date(data.createdAt),
  };
}

export async function deleteFavorite(id: string): Promise<void> {
  await apiClient.delete(`/favorites/${id}`);
}

export async function uploadFavoriteMusic(
  id: string,
  file: File,
): Promise<Favorite> {
  // Upload directly browser → Cloudinary (resource_type "video" accepts audio files too)
  const media = await uploadToCloudinary(file, "video", "taste-tapestry/music");
  const musicUrl = media.original_url;

  // Persist only the resulting URL to the backend
  const { data } = await apiClient.patch<Favorite>(`/favorites/${id}`, {
    fields: { musicUrl },
  });
  return {
    ...data,
    createdAt: new Date(data.createdAt),
  };
}

export async function trackFavoriteImpression(
  id: string,
): Promise<{ viewCount: number }> {
  const { data } = await apiClient.post<{ viewCount: number }>(
    `/favorites/${id}/view`,
  );
  return data;
}

export async function trackAnalyticsBatch(
  events: Array<{
    itemId: string;
    eventType: "impression" | "click";
    sessionId: string;
    source?: string;
    device?: string;
    platform?: string;
  }>
): Promise<void> {
  // Fire and forget
  await apiClient.post("/analytics/batch", { events });
}
